export default class BurningForest {
  grid = new Uint8Array(0);
  nextGrid = new Uint8Array(0);
  width = 0;
  height = 0;
  runtime = null;
  config = {
    treeDensity: 0.55,
    growthProbability: 0.01,
    spreadProbability: 1.0,
    lightningProbability: 0.0002,
    regrowthDelay: 8,
    wrapEdges: true
  };
  age = new Uint8Array(0);

  getApiVersion() {
    return "0.2";
  }

  getConfigSchema() {
    return {
      name: "Горящий лес",
      description: "Модель роста леса и распространения лесного пожара.",
      apiVersion: "0.2",
      params: {
        treeDensity: {
          type: "number",
          default: 0.55,
          label: "Начальная плотность леса",
          description: "Доля клеток, занятых деревьями при создании леса.",
          ui: "scroller",
          min: 0.05,
          max: 1,
          step: 0.05
        },
        growthProbability: {
          type: "number",
          default: 0.01,
          label: "Рост деревьев",
          description: "Вероятность появления дерева на пустой клетке за один шаг.",
          ui: "scroller",
          min: 0,
          max: 0.2,
          step: 0.005
        },
        spreadProbability: {
          type: "number",
          default: 1,
          label: "Распространение огня",
          description: "Вероятность воспламенения дерева от соседнего горящего дерева.",
          ui: "scroller",
          min: 0,
          max: 1,
          step: 0.05
        },
        lightningProbability: {
          type: "number",
          default: 0.0002,
          label: "Молния",
          description: "Вероятность случайного возгорания дерева за один шаг.",
          ui: "scroller",
          min: 0,
          max: 0.01,
          step: 0.0001
        },
        regrowthDelay: {
          type: "number",
          default: 8,
          label: "Восстановление",
          description: "Количество шагов, необходимых выгоревшей клетке перед восстановлением.",
          ui: "scroller",
          min: 0,
          max: 50,
          step: 1
        },
        wrapEdges: {
          type: "boolean",
          default: true,
          label: "Замкнутые границы",
          description: "Считать противоположные края сетки соседними.",
          ui: "checkbox"
        }
      },
      actions: {
        ignite: {
          label: "Поджечь лес",
          description: "Случайно поджечь одно дерево."
        },
        igniteCenter: {
          label: "Поджечь центр",
          description: "Поджечь дерево в центре леса."
        },
        reset: {
          label: "Новый лес",
          description: "Создать новый лес с текущей плотностью деревьев."
        },
        clear: {
          label: "Очистить",
          description: "Удалить все деревья и огонь."
        }
      }
    };
  }

  getConfig() {
    return { ...this.config };
  }

  setConfig(params) {
    const allowed = [
      "treeDensity",
      "growthProbability",
      "spreadProbability",
      "lightningProbability",
      "regrowthDelay",
      "wrapEdges"
    ];

    for (const key of allowed) {
      if (Object.prototype.hasOwnProperty.call(params, key)) {
        this.config[key] = params[key];
      }
    }

    return null;
  }

  init(ctx) {
    this.runtime = ctx.runtime;
    this.width = ctx.gridWidth;
    this.height = ctx.gridHeight;

    const size = this.width * this.height;
    this.grid = new Uint8Array(size);
    this.nextGrid = new Uint8Array(size);
    this.age = new Uint8Array(size);

    this.initializeForest();
  }

  initializeForest() {
    for (let i = 0; i < this.grid.length; i++) {
      this.age[i] = 0;
      this.grid[i] = Math.random() < this.config.treeDensity ? 1 : 0;
    }
  }

  getIndex(x, y) {
    if (this.config.wrapEdges) {
      x = (x + this.width) % this.width;
      y = (y + this.height) % this.height;
      return y * this.width + x;
    }

    if (x < 0 || x >= this.width || y < 0 || y >= this.height) {
      return -1;
    }

    return y * this.width + x;
  }

  hasBurningNeighbor(x, y) {
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) {
          continue;
        }

        const index = this.getIndex(x + dx, y + dy);

        if (index >= 0 && this.grid[index] === 2) {
          if (Math.random() <= this.config.spreadProbability) {
            return true;
          }
        }
      }
    }

    return false;
  }

  iterate(ctx) {
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const index = y * this.width + x;
        const state = this.grid[index];

        if (state === 0) {
          if (this.age[index] < 255) {
            this.age[index]++;
          }

          if (
            this.age[index] >= this.config.regrowthDelay &&
            Math.random() < this.config.growthProbability
          ) {
            this.nextGrid[index] = 1;
            this.age[index] = 0;
          } else {
            this.nextGrid[index] = 0;
          }
        } else if (state === 1) {
          if (this.hasBurningNeighbor(x, y)) {
            this.nextGrid[index] = 2;
            this.age[index] = 0;
          } else if (Math.random() < this.config.lightningProbability) {
            this.nextGrid[index] = 2;
            this.age[index] = 0;
          } else {
            this.nextGrid[index] = 1;
            this.age[index] = 0;
          }
        } else if (state === 2) {
          this.nextGrid[index] = 0;
          this.age[index] = 0;
        }
      }
    }

    const temp = this.grid;
    this.grid = this.nextGrid;
    this.nextGrid = temp;
  }

  render() {
    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: [
        "#101820",
        "#228B22",
        "#FF4500"
      ]
    };
  }

  runAction(actionId, payload) {
    switch (actionId) {
      case "ignite": {
        const trees = [];

        for (let i = 0; i < this.grid.length; i++) {
          if (this.grid[i] === 1) {
            trees.push(i);
          }
        }

        if (trees.length === 0) {
          this.runtime?.emitEvent({
            type: "warning",
            message: "В лесу нет деревьев для поджигания."
          });
          return;
        }

        const index = trees[Math.floor(Math.random() * trees.length)];
        this.grid[index] = 2;

        this.runtime?.emitEvent({
          type: "info",
          message: "Лес подожжён."
        });
        break;
      }

      case "igniteCenter": {
        const x = Math.floor(this.width / 2);
        const y = Math.floor(this.height / 2);
        const index = this.getIndex(x, y);

        if (index >= 0 && this.grid[index] === 1) {
          this.grid[index] = 2;
          this.runtime?.emitEvent({
            type: "info",
            message: "Центр леса подожжён."
          });
        } else {
          this.runtime?.emitEvent({
            type: "warning",
            message: "В центре нет дерева для поджигания."
          });
        }
        break;
      }

      case "reset": {
        this.initializeForest();
        this.runtime?.emitEvent({
          type: "info",
          message: "Создан новый лес."
        });
        break;
      }

      case "clear": {
        this.grid.fill(0);
        this.nextGrid.fill(0);
        this.age.fill(0);

        this.runtime?.emitEvent({
          type: "info",
          message: "Лес очищен."
        });
        break;
      }
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.age = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.runtime = null;
  }
}

export default class MyAutomaton {
  grid = new Uint8Array(0);
  nextGrid = new Uint8Array(0);
  width = 0;
  height = 0;
  runtime = null;
  row = 0;
  config = {
    rule: 30,
    initialMode: "center",
    density: 0.5,
    wrapEdges: true,
    autoRestart: true
  };

  getApiVersion() {
    return "0.2";
  }

  getConfigSchema() {
    return {
      name: "Одномерный автомат",
      description: "Классический одномерный клеточный автомат Вольфрама, разворачивающийся сверху вниз.",
      apiVersion: "0.2",
      params: {
        rule: {
          type: "number",
          default: 30,
          label: "Правило",
          description: "Номер правила Вольфрама от 0 до 255.",
          ui: "scroller",
          min: 0,
          max: 255,
          step: 1
        },
        initialMode: {
          type: "string",
          default: "center",
          label: "Начальное состояние",
          description: "Способ создания первого ряда.",
          ui: "combobox",
          options: ["center", "random", "single-left", "single-right"]
        },
        density: {
          type: "number",
          default: 0.5,
          label: "Плотность",
          description: "Плотность случайного первого ряда.",
          ui: "scroller",
          min: 0,
          max: 1,
          step: 0.01
        },
        wrapEdges: {
          type: "boolean",
          default: true,
          label: "Замыкать края",
          description: "Левая и правая границы считаются соседними.",
          ui: "checkbox"
        },
        autoRestart: {
          type: "boolean",
          default: true,
          label: "Автоперезапуск",
          description: "После заполнения экрана начать автомат заново.",
          ui: "checkbox"
        }
      },
      actions: {
        reset: {
          label: "Перезапустить",
          description: "Начать построение с первого ряда."
        },
        randomize: {
          label: "Случайный старт",
          description: "Создать новый случайный первый ряд."
        }
      }
    };
  }

  getConfig() {
    return { ...this.config };
  }

  setConfig(params) {
    if (!params || typeof params !== "object") return null;

    if (Number.isFinite(params.rule)) {
      this.config.rule = Math.max(0, Math.min(255, Math.floor(params.rule)));
    }
    if (typeof params.initialMode === "string" && ["center", "random", "single-left", "single-right"].includes(params.initialMode)) {
      this.config.initialMode = params.initialMode;
    }
    if (Number.isFinite(params.density)) {
      this.config.density = Math.max(0, Math.min(1, params.density));
    }
    if (typeof params.wrapEdges === "boolean") {
      this.config.wrapEdges = params.wrapEdges;
    }
    if (typeof params.autoRestart === "boolean") {
      this.config.autoRestart = params.autoRestart;
    }

    return null;
  }

  init(ctx) {
    this.runtime = ctx?.runtime ?? null;
    this.width = Math.max(1, Math.floor(ctx?.gridWidth ?? 100));
    this.height = Math.max(1, Math.floor(ctx?.gridHeight ?? 100));
    this.grid = new Uint8Array(this.width * this.height);
    this.nextGrid = new Uint8Array(this.width * this.height);
    this.resetGrid();
  }

  resetGrid() {
    this.grid.fill(0);
    this.nextGrid.fill(0);
    this.row = 0;

    if (this.width <= 0 || this.height <= 0) return;

    const y = 0;

    if (this.config.initialMode === "random") {
      for (let x = 0; x < this.width; x++) {
        this.grid[y * this.width + x] = Math.random() < this.config.density ? 1 : 0;
      }
    } else if (this.config.initialMode === "single-left") {
      this.grid[y * this.width] = 1;
    } else if (this.config.initialMode === "single-right") {
      this.grid[y * this.width + this.width - 1] = 1;
    } else {
      this.grid[y * this.width + Math.floor(this.width / 2)] = 1;
    }
  }

  buildNextRow() {
    if (this.row >= this.height - 1) return false;

    const sourceOffset = this.row * this.width;
    const targetOffset = (this.row + 1) * this.width;
    const rule = this.config.rule;

    for (let x = 0; x < this.width; x++) {
      let left;
      let center = this.grid[sourceOffset + x];
      let right;

      if (this.config.wrapEdges) {
        left = this.grid[sourceOffset + (x === 0 ? this.width - 1 : x - 1)];
        right = this.grid[sourceOffset + (x === this.width - 1 ? 0 : x + 1)];
      } else {
        left = x === 0 ? 0 : this.grid[sourceOffset + x - 1];
        right = x === this.width - 1 ? 0 : this.grid[sourceOffset + x + 1];
      }

      const pattern = (left << 2) | (center << 1) | right;
      this.nextGrid[targetOffset + x] = (rule >> pattern) & 1;
    }

    this.row++;
    return true;
  }

  iterate(ctx) {
    if (this.width <= 0 || this.height <= 0) return;

    if (this.row >= this.height - 1) {
      if (this.config.autoRestart) {
        this.resetGrid();
      } else {
        this.runtime?.requestPause();
      }
      return;
    }

    this.buildNextRow();
  }

  render() {
    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: ["#050816", "#7dd3fc"]
    };
  }

  runAction(actionId) {
    switch (actionId) {
      case "reset":
        this.resetGrid();
        this.runtime?.emitEvent({
          type: "info",
          message: "Автомат перезапущен."
        });
        break;

      case "randomize":
        this.config.initialMode = "random";
        this.resetGrid();
        this.runtime?.emitEvent({
          type: "info",
          message: "Создан новый случайный первый ряд."
        });
        break;
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.row = 0;
    this.runtime = null;
  }
}

export default class MyAutomaton {
  grid = new Uint8Array(0);
  nextGrid = new Uint8Array(0);
  width = 0;
  height = 0;
  runtime = null;
  config = {
    material: "sand",
    density: 0.35,
    gravity: "normal",
    wind: 0,
    maxPileHeight: 0,
    wrapEdges: false,
    source: "top",
    sourceWidth: 0.35,
    obstacleMode: "random",
    obstacleDensity: 0.06
  };

  getApiVersion() { return "0.2"; }

  getConfigSchema() {
    return {
      name: "Песок",
      description: "Падающий песок, насыпи и препятствия.",
      apiVersion: "0.2",
      params: {
        material: {
          type: "string", default: "sand", label: "Материал",
          description: "Тип падающего материала.", ui: "combobox",
          options: ["sand", "heavy-sand", "gravel"]
        },
        density: {
          type: "number", default: 0.35, label: "Плотность потока",
          description: "Вероятность появления новых песчинок.", ui: "scroller",
          min: 0, max: 1, step: 0.01
        },
        gravity: {
          type: "string", default: "normal", label: "Гравитация",
          description: "Скорость и характер осыпания.", ui: "combobox",
          options: ["slow", "normal", "fast"]
        },
        wind: {
          type: "number", default: 0, label: "Ветер",
          description: "Направление и сила горизонтального смещения.", ui: "scroller",
          min: -1, max: 1, step: 0.1
        },
        maxPileHeight: {
          type: "number", default: 0, label: "Макс. высота насыпи",
          description: "Ограничение высоты слоя. 0 = без ограничения.", ui: "scroller",
          min: 0, max: 100, step: 1
        },
        wrapEdges: {
          type: "boolean", default: false, label: "Замыкать края",
          description: "Песок выходит справа и появляется слева.", ui: "checkbox"
        },
        source: {
          type: "string", default: "top", label: "Источник",
          description: "Откуда появляется песок.", ui: "combobox",
          options: ["top", "both-sides", "center"]
        },
        sourceWidth: {
          type: "number", default: 0.35, label: "Ширина источника",
          description: "Доля ширины сетки, через которую сыпется песок.", ui: "scroller",
          min: 0.05, max: 1, step: 0.05
        },
        obstacleMode: {
          type: "string", default: "random", label: "Препятствия",
          description: "Способ размещения препятствий.", ui: "combobox",
          options: ["none", "random", "platforms", "walls"]
        },
        obstacleDensity: {
          type: "number", default: 0.06, label: "Плотность препятствий",
          description: "Количество случайных препятствий.", ui: "scroller",
          min: 0, max: 0.3, step: 0.01
        }
      },
      actions: {
        reset: { label: "Очистить", description: "Очистить сетку и создать препятствия заново." },
        addSand: { label: "Добавить песок", description: "Добавить порцию песка в источник." },
        clearObstacles: { label: "Убрать препятствия", description: "Удалить все препятствия." },
        randomObstacles: { label: "Новые препятствия", description: "Создать новый набор препятствий." }
      }
    };
  }

  getConfig() { return { ...this.config }; }

  setConfig(params) {
    if (!params || typeof params !== "object") return null;

    if (typeof params.material === "string" && ["sand", "heavy-sand", "gravel"].includes(params.material)) this.config.material = params.material;
    if (Number.isFinite(params.density)) this.config.density = Math.max(0, Math.min(1, params.density));
    if (typeof params.gravity === "string" && ["slow", "normal", "fast"].includes(params.gravity)) this.config.gravity = params.gravity;
    if (Number.isFinite(params.wind)) this.config.wind = Math.max(-1, Math.min(1, params.wind));
    if (Number.isFinite(params.maxPileHeight)) this.config.maxPileHeight = Math.max(0, Math.floor(params.maxPileHeight));
    if (typeof params.wrapEdges === "boolean") this.config.wrapEdges = params.wrapEdges;
    if (typeof params.source === "string" && ["top", "both-sides", "center"].includes(params.source)) this.config.source = params.source;
    if (Number.isFinite(params.sourceWidth)) this.config.sourceWidth = Math.max(0.05, Math.min(1, params.sourceWidth));
    if (typeof params.obstacleMode === "string" && ["none", "random", "platforms", "walls"].includes(params.obstacleMode)) this.config.obstacleMode = params.obstacleMode;
    if (Number.isFinite(params.obstacleDensity)) this.config.obstacleDensity = Math.max(0, Math.min(0.3, params.obstacleDensity));

    return null;
  }

  init(ctx) {
    this.runtime = ctx?.runtime ?? null;
    this.width = Math.max(1, Math.floor(ctx?.gridWidth ?? 100));
    this.height = Math.max(1, Math.floor(ctx?.gridHeight ?? 100));
    this.grid = new Uint8Array(this.width * this.height);
    this.nextGrid = new Uint8Array(this.width * this.height);
    this.createObstacles();
  }

  isObstacle(v) { return v === 2; }
  isSand(v) { return v === 1 || v === 3 || v === 4; }

  getMaterialValue() {
    if (this.config.material === "heavy-sand") return 3;
    if (this.config.material === "gravel") return 4;
    return 1;
  }

  clearSand() {
    for (let i = 0; i < this.grid.length; i++) {
      if (this.isSand(this.grid[i])) this.grid[i] = 0;
    }
  }

  createObstacles() {
    this.grid.fill(0);
    if (this.config.obstacleMode === "none") return;

    if (this.config.obstacleMode === "random") {
      const startY = Math.floor(this.height * 0.2);
      for (let y = startY; y < this.height - 3; y++) {
        for (let x = 0; x < this.width; x++) {
          if (Math.random() < this.config.obstacleDensity) this.grid[y * this.width + x] = 2;
        }
      }
    } else if (this.config.obstacleMode === "platforms") {
      const count = Math.max(2, Math.floor(this.height / 14));
      for (let i = 0; i < count; i++) {
        const y = 8 + Math.floor((i + 1) * this.height / (count + 1));
        const length = Math.max(5, Math.floor(this.width * (0.15 + Math.random() * 0.3)));
        const start = Math.floor(Math.random() * Math.max(1, this.width - length));
        for (let x = start; x < Math.min(this.width, start + length); x++) {
          this.grid[y * this.width + x] = 2;
        }
      }
    } else if (this.config.obstacleMode === "walls") {
      const center = Math.floor(this.width / 2);
      const gap = Math.max(2, Math.floor(this.width * 0.05));
      for (let y = Math.floor(this.height * 0.3); y < Math.floor(this.height * 0.8); y++) {
        for (let x = 0; x < this.width; x++) {
          if (Math.abs(x - center) > gap && Math.random() < 0.75) this.grid[y * this.width + x] = 2;
        }
      }
    }
  }

  addSandParticle(x, y) {
    if (x < 0 || x >= this.width || y < 0 || y >= this.height) return false;
    const i = y * this.width + x;
    if (this.grid[i] === 0) {
      this.grid[i] = this.getMaterialValue();
      return true;
    }
    return false;
  }

  emitSand() {
    const count = Math.max(1, Math.floor(this.width * this.config.density * 0.12));
    const sourceWidth = Math.max(1, Math.floor(this.width * this.config.sourceWidth));
    const center = Math.floor(this.width / 2);
    const start = Math.max(0, center - Math.floor(sourceWidth / 2));

    for (let n = 0; n < count; n++) {
      let x;
      if (this.config.source === "center") {
        x = center + Math.floor((Math.random() - 0.5) * Math.max(2, sourceWidth * 0.25));
      } else if (this.config.source === "both-sides") {
        x = Math.random() < 0.5
          ? Math.floor(Math.random() * Math.max(1, sourceWidth / 2))
          : this.width - 1 - Math.floor(Math.random() * Math.max(1, sourceWidth / 2));
      } else {
        x = start + Math.floor(Math.random() * sourceWidth);
      }
      this.addSandParticle(Math.max(0, Math.min(this.width - 1, x)), 0);
    }
  }

  canMoveTo(x, y) {
    if (y < 0 || y >= this.height) return false;
    if (this.config.wrapEdges) x = (x + this.width) % this.width;
    if (x < 0 || x >= this.width) return false;
    return this.grid[y * this.width + x] === 0;
  }

  targetX(x) {
    if (this.config.wrapEdges) return (x + this.width) % this.width;
    return x;
  }

  moveSand(fromX, fromY, toX, toY) {
    toX = this.targetX(toX);
    if (toX < 0 || toX >= this.width || toY < 0 || toY >= this.height) return false;
    const from = fromY * this.width + fromX;
    const to = toY * this.width + toX;
    if (this.grid[to] !== 0) return false;
    this.nextGrid[to] = this.grid[from];
    this.nextGrid[from] = 0;
    return true;
  }

  iterate(ctx) {
    if (!this.grid.length) return;

    this.emitSand();
    this.nextGrid.set(this.grid);

    const passes = this.config.gravity === "fast" ? 2 : 1;
    const direction = this.config.wind > 0 ? 1 : -1;
    const windChance = Math.abs(this.config.wind);

    for (let pass = 0; pass < passes; pass++) {
      for (let y = this.height - 2; y >= 0; y--) {
        const leftToRight = ((ctx?.step ?? 0) + y + pass) % 2 === 0;
        const start = leftToRight ? 0 : this.width - 1;
        const end = leftToRight ? this.width : -1;
        const step = leftToRight ? 1 : -1;

        for (let x = start; x !== end; x += step) {
          const i = y * this.width + x;
          if (!this.isSand(this.grid[i])) continue;

          const below = (y + 1) * this.width + x;
          if (this.grid[below] === 0) {
            this.nextGrid[below] = this.grid[i];
            this.nextGrid[i] = 0;
            continue;
          }

          let first = Math.random() < 0.5 ? -1 : 1;
          if (this.config.wind !== 0 && Math.random() < windChance) first = direction;
          const second = -first;

          const candidates = [first, second];
          let moved = false;

          for (let c = 0; c < candidates.length; c++) {
            const dx = candidates[c];
            let nx = x + dx;
            if (this.config.wrapEdges) nx = (nx + this.width) % this.width;
            if (nx < 0 || nx >= this.width) continue;

            const diagonal = (y + 1) * this.width + nx;
            if (this.grid[diagonal] === 0) {
              this.nextGrid[diagonal] = this.grid[i];
              this.nextGrid[i] = 0;
              moved = true;
              break;
            }
          }

          if (!moved && this.config.wind !== 0 && Math.random() < windChance * 0.35) {
            let nx = x + direction;
            if (this.config.wrapEdges) nx = (nx + this.width) % this.width;
            if (nx >= 0 && nx < this.width && this.grid[y * this.width + nx] === 0) {
              this.nextGrid[y * this.width + nx] = this.grid[i];
              this.nextGrid[i] = 0;
            }
          }
        }
      }
      this.grid.set(this.nextGrid);
    }

    if (this.config.maxPileHeight > 0) this.limitPileHeight();
  }

  limitPileHeight() {
    const max = this.config.maxPileHeight;
    for (let x = 0; x < this.width; x++) {
      let run = 0;
      for (let y = this.height - 1; y >= 0; y--) {
        const i = y * this.width + x;
        if (this.isSand(this.grid[i])) {
          run++;
          if (run > max) this.grid[i] = 0;
        } else if (this.grid[i] === 0) {
          if (run > 0) break;
        } else {
          run = 0;
        }
      }
    }
  }

  render() {
    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: ["#10131a", "#d9b45f", "#7d8794", "#a8753e", "#b8a06a"]
    };
  }

  runAction(actionId) {
    switch (actionId) {
      case "reset":
        this.createObstacles();
        this.runtime?.emitEvent({ type: "info", message: "Сетка очищена, препятствия созданы заново." });
        break;
      case "addSand":
        for (let i = 0; i < Math.max(10, Math.floor(this.width * 0.2)); i++) this.emitSand();
        break;
      case "clearObstacles":
        for (let i = 0; i < this.grid.length; i++) {
          if (this.grid[i] === 2) this.grid[i] = 0;
        }
        this.runtime?.emitEvent({ type: "info", message: "Все препятствия удалены." });
        break;
      case "randomObstacles":
        this.clearSand();
        this.createObstacles();
        this.runtime?.emitEvent({ type: "info", message: "Создан новый набор препятствий." });
        break;
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.runtime = null;
  }
}

