    // 4x4 окрестность: две клетки в каждую сторону.
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        if (dx === 0 && dy === 0) continue;
        // Обрезаем угловые позиции, чтобы получить 4x4 симметричную область
        // вокруг клетки с радиусом 2.
        if (Math.abs(dx) === 2 && Math.abs(dy) === 2) continue;
        count += this.getCell(x + dx, y + dy);
