      for (let y = 0; y < this.height; y++) {
        for (let x = 0; x < this.width; x++) {
          if ((Math.floor(x / 5) + Math.floor(y / 5)) % 2 === 0 && Math.random() < this.config.density * 1.8) {
            this.grid[y * this.width + x] = 1;
          }
        }
      }
      return;
    }

    for (let i = 0; i < this.grid.length; i++) {
      this.grid[i] = Math.random() < this.config.density ? 1 : 0;
    }
  }

  seedCluster(cx, cy, radius) {
    for (let y = cy - radius; y <= cy + radius; y++) {
      for (let x = cx - radius; x <= cx + radius; x++) {
        if (x < 0 || x >= this.width || y < 0 || y >= this.height) continue;

        const dx = x - cx;
        const dy = y - cy;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance <= radius && Math.random() < 0.68) {
          this.grid[y * this.width + x] = 1;
        }
      }
    }
  }

  getCell(x, y) {
    if (this.config.wrapEdges) {
      x = (x + this.width) % this.width;
      y = (y + this.height) % this.height;
      return this.grid[y * this.width + x];
    }

    if (x < 0 || x >= this.width || y < 0 || y >= this.height) {
      return 0;
    }

    return this.grid[y * this.width + x];
  }

  countNeighbors(x, y) {
    let count = 0;

    // Полная квадратная окрестность 5x5.
    // Центральная клетка исключается, поэтому максимум = 24.
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        if (dx === 0 && dy === 0) continue;
        count += this.getCell(x + dx, y + dy);
      }
    }

    return count;
  }

  iterate(ctx) {
    if (!this.grid.length) return;

    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const i = y * this.width + x;
        const alive = this.grid[i] !== 0;
        const neighbors = this.countNeighbors(x, y);
        let next = 0;

        if (alive) {
          if (neighbors >= this.config.surviveMin && neighbors <= this.config.surviveMax) {
            if (this.config.aging) {
              next = Math.min(4, this.grid[i] + 1);
            } else {
              next = 1;
            }
          }
        } else {
          if (neighbors >= this.config.birthMin && neighbors <= this.config.birthMax) {
            next = 1;
          }
        }

        this.nextGrid[i] = next;
      }
    }

    const temp = this.grid;
    this.grid = this.nextGrid;
    this.nextGrid = temp;
  }

  render() {
    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: this.config.aging
        ? ["#03050a", "#f4d35e", "#eea93a", "#e76f51", "#b83b5e"]
        : ["#03050a", "#f4d35e"]
    };
  }

  runAction(actionId) {
    switch (actionId) {
      case "reset":
        this.seed();
        this.runtime?.emitEvent({
          type: "info",
          message: "Автомат 5x5 перезапущен."
        });
        break;

      case "randomize":
        this.config.initialMode = "random";
        this.seed();
        this.runtime?.emitEvent({
          type: "info",
          message: "Создано новое случайное поле."
        });
        break;

      case "clear":
        this.grid.fill(0);
        this.nextGrid.fill(0);
        break;

      case "pulse":
        this.grid.fill(0);
        this.nextGrid.fill(0);
        this.seedCluster(
          Math.floor(this.width / 2),
          Math.floor(this.height / 2),
          Math.max(4, Math.floor(Math.min(this.width, this.height) * 0.06))
        );
        break;
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.runtime = null;
  }
}

