  seed() {
    this.grid.fill(0);
    this.nextGrid.fill(0);

    const mode = this.config.initialMode;

    if (mode === "center") {
      this.createCenterCluster();
      return;
    }

    if (mode === "rings") {
      this.createRings();
      return;
    }

    if (mode === "cross") {
      this.createCross();
      return;
    }

    for (let i = 0; i < this.grid.length; i++) {
      if (mode === "noise") {
        const localDensity = this.config.density * (0.5 + Math.random());
        this.grid[i] = Math.random() < localDensity ? 1 : 0;
      } else {
        this.grid[i] = Math.random() < this.config.density ? 1 : 0;
      }
    }
  }

  createCenterCluster() {
    const cx = Math.floor(this.width / 2);
    const cy = Math.floor(this.height / 2);
    const radius = Math.max(3, Math.floor(Math.min(this.width, this.height) * 0.07));

    for (let y = cy - radius; y <= cy + radius; y++) {
      for (let x = cx - radius; x <= cx + radius; x++) {
        if (x < 0 || x >= this.width || y < 0 || y >= this.height) continue;
        const dx = x - cx;
        const dy = y - cy;
        if (dx * dx + dy * dy <= radius * radius && Math.random() < 0.75) {
          this.grid[y * this.width + x] = 1;
        }
      }
    }
  }

  createRings() {
    const cx = (this.width - 1) / 2;
    const cy = (this.height - 1) / 2;
    const maxRadius = Math.min(this.width, this.height) * 0.42;

    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const dx = x - cx;
        const dy = y - cy;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const wave = Math.sin(distance * 0.75);

        if (distance < maxRadius && wave > 0.72 && Math.random() < 0.85) {
          this.grid[y * this.width + x] = 1;
        }
      }
    }
  }

  createCross() {
    const cx = Math.floor(this.width / 2);
    const cy = Math.floor(this.height / 2);
    const thickness = Math.max(1, Math.floor(Math.min(this.width, this.height) * 0.025));

    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (Math.abs(x - cx) <= thickness || Math.abs(y - cy) <= thickness) {
          if (Math.random() < 0.72) this.grid[y * this.width + x] = 1;
        }
      }
    }
  }

  getCell(x, y) {
    if (this.config.wrapEdges) {
      x = (x + this.width) % this.width;
      y = (y + this.height) % this.height;
      return this.grid[y * this.width + x];
    }

    if (x < 0 || x >= this.width || y < 0 || y >= this.height) return 0;
    return this.grid[y * this.width + x];
  }

  countActiveNeighbors(x, y) {
    let count = 0;

    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        if (this.getCell(x + dx, y + dy) === 1) count++;
      }
    }

    return count;
  }

  iterate(ctx) {
    if (!this.grid.length) return;

    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const i = y * this.width + x;
        const state = this.grid[i];

        if (state === 1) {
          // Активная клетка всегда становится восстанавливающейся.
          this.nextGrid[i] = this.config.decaySteps > 1 ? 2 : 0;
          continue;
        }

        if (state >= 2) {
          if (this.config.decaySteps <= 1) {
            this.nextGrid[i] = 0;
          } else {
            const age = state - 1;
            this.nextGrid[i] = age < this.config.decaySteps ? state + 1 : 0;
          }
          continue;
        }

        const neighbors = this.countActiveNeighbors(x, y);
        const shouldActivate = neighbors >= this.config.birthMin && neighbors <= this.config.birthMax;
        const randomPulse = this.config.pulseChance > 0 && Math.random() < this.config.pulseChance;

        this.nextGrid[i] = shouldActivate || randomPulse ? 1 : 0;
      }
    }

    const temp = this.grid;
    this.grid = this.nextGrid;
    this.nextGrid = temp;
  }

  render() {
    if (!this.config.aging) {
      return {
        type: "grid",
        width: this.width,
        height: this.height,
        cells: this.grid,
        palette: ["#020617", "#67e8f9", "#082f49"]
      };
    }

    return {
      type: "grid",
      width: this.width,
      height: this.height,
      cells: this.grid,
      palette: [
        "#020617",
        "#67e8f9",
        "#155e75",
        "#164e63",
        "#1e3a4a",
        "#172f3b",
        "#122631",
        "#0d1d26",
        "#09151c",
        "#061017"
      ]
    };
  }

  runAction(actionId) {
    switch (actionId) {
      case "reset":
        this.seed();
        this.runtime?.emitEvent({
          type: "info",
          message: "Мозг Брайана перезапущен."
        });
        break;

      case "randomize":
        this.config.initialMode = "random";
        this.seed();
        this.runtime?.emitEvent({
          type: "info",
          message: "Создано новое случайное поле."
        });
        break;

      case "clear":
        this.grid.fill(0);
        this.nextGrid.fill(0);
        break;

      case "pulse": {
        this.grid.fill(0);
        this.nextGrid.fill(0);

        const cx = Math.floor(this.width / 2);
        const cy = Math.floor(this.height / 2);
        const length = Math.max(5, Math.floor(Math.min(this.width, this.height) * 0.12));

        for (let x = cx - length; x <= cx + length; x++) {
          if (x >= 0 && x < this.width) {
            this.grid[cy * this.width + x] = 1;
          }
        }

        for (let y = cy - length; y <= cy + length; y++) {
          if (y >= 0 && y < this.height) {
            this.grid[y * this.width + cx] = 1;
          }
        }
        break;
      }

      case "explosion": {
        this.grid.fill(0);
        this.nextGrid.fill(0);

        const cx = Math.floor(this.width / 2);
        const cy = Math.floor(this.height / 2);
        const radius = Math.max(5, Math.floor(Math.min(this.width, this.height) * 0.13));

        for (let y = cy - radius; y <= cy + radius; y++) {
          for (let x = cx - radius; x <= cx + radius; x++) {
            if (x < 0 || x >= this.width || y < 0 || y >= this.height) continue;

            const dx = x - cx;
            const dy = y - cy;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance <= radius && Math.random() < 0.62) {
              this.grid[y * this.width + x] = 1;
            }
          }
        }
        break;
      }
    }
  }

  destroy() {
    this.grid = new Uint8Array(0);
    this.nextGrid = new Uint8Array(0);
    this.width = 0;
    this.height = 0;
    this.runtime = null;
  }
}
